questions.solution:
let checked = 0;
let failed = 0;

for (let total = 0; total <= 20; total++) {
  for (let people = 1; people <= 5; people++) {
    const base = Math.floor(total / people);
    const extra = total % people;
    let sum = 0;
    for (let person = 1; person <= people; person++) {
      let share = base;
      if (person <= extra) {
        share = base + 1;
      }
      sum = sum + share;
    }
    checked = checked + 1;
    if (sum !== total) {
      failed = failed + 1;
    }
  }
}

console.log("Checked", checked, "cases,", failed, "failed");

